emidentificationtypecode'),(530,1,'AdditionalTradeItemIdentificationTypeCode','FOR_INTERNAL_USE_8','For internal use 8','Internal identification used for mapping purposes.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(531,1,'AdditionalTradeItemIdentificationTypeCode','FOR_INTERNAL_USE_9','For internal use 9','Internal identification used for mapping purposes.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(532,1,'AdditionalTradeItemIdentificationTypeCode','GDPA','General Directorate of Pharmaceutical Affairs (GDPA)','General Directorate of Pharmaceutical Affairs (GDPA) manages the market authorisation of healthcare products in Afghanistan - AF',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(533,1,'AdditionalTradeItemIdentificationTypeCode','GTIN_12','GTIN 12','The 12-digit GS1 Identification Key composed of a U.P.C. Company Prefix, Item Reference, and Check Digit used to identify trade items.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(534,1,'AdditionalTradeItemIdentificationTypeCode','GTIN_13','GTIN 13','The 13-digit GS1 Identification Key composed of a GS1 Company Prefix, Item Reference, and Check Digit used to identify trade items.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(535,1,'AdditionalTradeItemIdentificationTypeCode','GTIN_14','GTIN 14','The 14-digit GS1 Identification Key composed of an Indicator digit (1-9), GS1 Company Prefix, Item Reference, and Check Digit used to identify trade items.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(536,1,'AdditionalTradeItemIdentificationTypeCode','GTIN_8','GTIN 8','The 8-digit GS1 Identification Key composed of a GS1-8 Prefix, Item Reference, and Check Digit used to identify trade items.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(537,1,'AdditionalTradeItemIdentificationTypeCode','HIBC','HIBC','Health Industry Business Communication Barcode:  An alphanumeric identification number used as a common identifier within the healthcare industry across different locations. In the Netherlands, this code is managed by the European Health Industry Business Communications Council.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(538,1,'AdditionalTradeItemIdentificationTypeCode','ICCBBA','ICCBBA',' ICCBBA is an international non-governmental organization (NGO) that manages, develops and licenses ISBT 128; the international information standard for the terminology, coding and labelling of medical products of human origin.  ICCBBA manage the allocation of globally unique identifiers to licensed facilities and maintain the ISBT 128 Standard, international databases for Facility Identification Numbers and Product Coding, supporting documentation, and educational materials.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(539,1,'AdditionalTradeItemIdentificationTypeCode','INDUSTRY_ASSIGNED','Industry Assigned','A unique proprietary identification number assigned by an industry sector association or other organisation, used to identify an item or service. Typically the association or organisation provides the industry sector with an identification number as key identifier of a type of trade item.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(540,1,'AdditionalTradeItemIdentificationTypeCode','INVIMA','Instituto Nacional de Vigilancia de Medicamentos y Alimentos (INVIMA)','Instituto Nacional de Vigilancia de Medicamentos y Alimentos (INVIMA) manages the market authorisation of healthcare products in Colombia - CO',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(541,1,'AdditionalTradeItemIdentificationTypeCode','ISBN_NUMBER','ISBN number','International Standard Book Number:  A unique numeric commercial book identifier.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(542,1,'AdditionalTradeItemIdentificationTypeCode','ISSN_NUMBER','ISSN number','International Standard Serial Number:  unique eight-digit number used to identify a print or electronic periodical publication.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(543,1,'AdditionalTradeItemIdentificationTypeCode','JFDA','Jordan Food and Drug Administration','Jordan Food and Drug Administration manages the market authorisation of healthcare products in Jordan - JO',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(544,1,'AdditionalTradeItemIdentificationTypeCode','LMHPRA','Liberia Medicines and Health Products Regulatory Authority','Liberia Medicines and Health Products Regulatory Authority manages the market authorisation of healthcare products in Liberia - LR',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(545,1,'AdditionalTradeItemIdentificationTypeCode','LOTTERY_GAME_NUMBER','Lottery Game Number','Unknown',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(546,1,'AdditionalTradeItemIdentificationTypeCode','LOTTERY_PACK_BOOK_NUMBER','Lottery pack book number','A unique identifier for a book of shrink-wrapped lottery game tickets.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(547,1,'AdditionalTradeItemIdentificationTypeCode','MANUFACTURER_PART_NUMBER','Manufacturer part number','The additional Trade Item Identification value populated is an identifier of a part used for an item.  While the name implies that the number is assigned by the manufacturer, the part may be built by one manufacturer to apply to another manufacturer’s item.  In this case this number is the applicable part number from the item’s manufacturer.  The part manufacturer numbers would be found with the type of MODEL_NUMBER, SUPPLIER_ASSIGNED, or DISTRIBUTOR_ASSIGNED.  For example, a 1957 car manufactured by Chevrolet has a part number AB123 which is the driver’s door handle.  A secondary manufacture produces an equivalent or Original Equipment Manufacturer (OEM) part with their number of 57-123CHEV.  This value would be the AB123 to signify that it is that equivalent.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(548,1,'AdditionalTradeItemIdentificationTypeCode','MCAZ','Medicines Control Authority of Zimbabwe (MCAZ)','Medicines Control Authority of Zimbabwe (MCAZ) manages the market authorisation of healthcare products in Zimbabwe - ZW',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(549,1,'AdditionalTradeItemIdentificationTypeCode','MCC','Medicines Control Council (MCC)','Medicines Control Council (MCC) manages the market authorisation of healthcare products in South Africa - ZA',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(550,1,'AdditionalTradeItemIdentificationTypeCode','MDL','MDL','The Canadian Medical Device License (MDL) is required for companies which sell Class II, III, and IV medical devices in Canada. The MDL is a product approval and should not be confused with the MDEL which is a permit for the company/distributor itself.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(551,1,'AdditionalTradeItemIdentificationTypeCode','MINSA','Ministerio de Salud - Direccion de Farmacias (MINSA)','Ministerio de Salud - Direccion de Farmacias (MINSA) manages the market authorisation of healthcare products in Nicaragua - NI',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(552,1,'AdditionalTradeItemIdentificationTypeCode','MISAU','Departamento Farmacêutico-MISAU','Departamento Farmacêutico-MISAU manages the market authorisation of healthcare products in Mozambique - MZ',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(553,1,'AdditionalTradeItemIdentificationTypeCode','MODEL_NUMBER','Model Number','The additional Trade Item Identification value populated is an identification number which defines the configuration of the product in addition to the Item number.  This is typically printed or otherwise attached to an item.  In electronics, this number is typically found around or near a serial number.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(554,1,'AdditionalTradeItemIdentificationTypeCode','MOH_AO','Ministry of Health (MOH) Angola','Ministry of Health (MOH) manages the market authorisation of healthcare products in Angola - AO',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(555,1,'AdditionalTradeItemIdentificationTypeCode','MOH_BB','Ministry of Health (MOH)  Barbados ','Ministry of Health (MOH) manages the market authorisation of healthcare products in Barbados - BB',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(556,1,'AdditionalTradeItemIdentificationTypeCode','MOH_BW','Drugs Regulatory Unit (DRU) of the Ministry of Health (MOH)','Drugs Regulatory Unit (DRU) of the Ministry of Health (MOH) manages the market authorisation of healthcare products in Botswana - BW',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(557,1,'AdditionalTradeItemIdentificationTypeCode','MOH_GY','Ministry of Health - Guyana ','Ministry of Health manages the market authorisation of healthcare products in Guyana - GY',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(558,1,'AdditionalTradeItemIdentificationTypeCode','MOH_MA','Ministry of Health - Morocco ','Ministry of Health manages the market authorisation of healthcare products in Morocco - MA',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(559,1,'AdditionalTradeItemIdentificationTypeCode','MOH_MR','Ministry of Health: Pharmacy and Laboratory','Ministry of Health: Pharmacy and Laboratory manages the market authorisation of healthcare products in Mauritania - MR',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(560,1,'AdditionalTradeItemIdentificationTypeCode','MOH_RW','Ministry of Health - Rwanda ','Ministry of Health manages the market authorisation of healthcare products in Rwanda - RW',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(561,1,'AdditionalTradeItemIdentificationTypeCode','MOH_SZ','Ministry of Health (MOH) Swaziland','Ministry of Health (MOH) manages the market authorisation of healthcare products in Swaziland - SZ',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(562,1,'AdditionalTradeItemIdentificationTypeCode','MOH_TJ','Ministry of Health - Tajikistan ','Ministry of Health manages the market authorisation of healthcare products in Tajikistan - TJ',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(563,1,'AdditionalTradeItemIdentificationTypeCode','MOH_TT','Chemistry Food and Drugs Division/Ministry of Health (CFFD/MOH)','Chemistry Food and Drugs Division/Ministry of Health (CFFD/MOH) manages the market authorisation of healthcare products in Trinidad and Tobago - TT',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(564,1,'AdditionalTradeItemIdentificationTypeCode','MOH_UG','National Drug Authority','National Drug Authority manages the market authorisation of healthcare products in Uganda - UG',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(565,1,'AdditionalTradeItemIdentificationTypeCode','MOH_UZ','Ministry of Health - Uzbekistan','Ministry of Health manages the market authorisation of healthcare products in Uzbekistan - UZ',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(566,1,'AdditionalTradeItemIdentificationTypeCode','MOHSW','Ministry of Health & Social Welfare','Ministry of Health & Social Welfare manages the market authorisation of healthcare products in Gambia - GM',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(567,1,'AdditionalTradeItemIdentificationTypeCode','MOPH_NE','Ministry of Public Health','Ministry of Public Health manages the market authorisation of healthcare products in Niger - NE',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(568,1,'AdditionalTradeItemIdentificationTypeCode','MOPH_TD','Minister of Public Health: Direction de la Pharmacie, du Médicament et des Laboratoires','Minister of Public Health: Direction de la Pharmacie, du Médicament et des Laboratoires manages the market authorisation of healthcare products in Chad - TD',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(569,1,'AdditionalTradeItemIdentificationTypeCode','MRA','Medicines Regulatory Authority (MRA) Palestine','Medicines Regulatory Authority (MRA) manages the market authorisation of healthcare products in Palestine, State of - PS',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(570,1,'AdditionalTradeItemIdentificationTypeCode','MRA_PG','Medicines Regulatory Authority (MRA) Papua New Guinea','Medicines Regulatory Authority (MRA) manages the market authorisation of healthcare products in Papua New Guinea - PG',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(571,1,'AdditionalTradeItemIdentificationTypeCode','MRA_SS','Medicines Regulatory Authority (MRA) South Sudan ','Medicines Regulatory Authority (MRA) manages the market authorisation of healthcare products in South Sudan - SS',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(572,1,'AdditionalTradeItemIdentificationTypeCode','MSD','Unidad de Medicamentos y Tecnología en Salud (MSD)','Unidad de Medicamentos y Tecnología en Salud (MSD) manages the market authorisation of healthcare products in Bolivia - BO',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(573,1,'AdditionalTradeItemIdentificationTypeCode','MSP','Direccion General de Drogas y Farmacias del Ministerio de Salud Pública (DGDF/MSP)','Direccion General de Drogas y Farmacias del Ministerio de Salud Pública (DGDF/MSP) manages the market authorisation of healthcare products in Dominican Republic - DO',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(574,1,'AdditionalTradeItemIdentificationTypeCode','MSPAS_CG','Ministère de la Santé Publique et des Affairs Sociales: Direction des Pharmacies, du Médicament et des Laboratoires ','Ministère de la Santé Publique et des Affairs Sociales: Direction des Pharmacies, du Médicament et des Laboratoires  manages the market authorisation of healthcare products in Congo, Republic of - CG',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(575,1,'AdditionalTradeItemIdentificationTypeCode','MSPAS_GT','Minsiterio de Salud Publica y Asistencia Social/Departamento de Regulación y Control de Productos Farmacéuticos y Afines (MSPAS)','Minsiterio de Salud Publica y Asistencia Social/Departamento de Regulación y Control de Productos Farmacéuticos y Afines (MSPAS) manages the market authorisation of healthcare products in Guatemala - GT',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(576,1,'AdditionalTradeItemIdentificationTypeCode','MSPBS','Ministerio de Salud Pública y Bienestar Social (MSPBS)','Ministerio de Salud Pública y Bienestar Social (MSPBS) manages the market authorisation of healthcare products in Paraguay - PY',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(577,1,'AdditionalTradeItemIdentificationTypeCode','NABCA_PRODUCT_CODE','NABCA product code','A product code issued by the National Alcohol Beverage Control Association in the United States.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(578,1,'AdditionalTradeItemIdentificationTypeCode','NADFC','National Agency of Drug and Food Control (NADFC)','National Agency of Drug and Food Control (NADFC) manages the market authorisation of healthcare products in Indonesia - ID',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(579,1,'AdditionalTradeItemIdentificationTypeCode','NAFDAC_NG','National Agency for Food and Drug Administration and Control (NAFDAC)','National Agency for Food and Drug Administration and Control (NAFDAC) manages the market authorisation of healthcare products in Nigeria - NG',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(580,1,'AdditionalTradeItemIdentificationTypeCode','NAN','NAN','Nordic Article Number is a 6 digit identification number needed on all human and veterinary pharmaceuticals licensed in Sweden. The number is unique for a certain packages. A NAN can be valid in one to five Nordic countries (Sweden, Denmark, Norway, Finland and Iceland) depending on if the package fulfils some basic criteria.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(581,1,'AdditionalTradeItemIdentificationTypeCode','NAPPI','National Pharmaceutical Product Index','National Pharmaceutical Product Index-  The National Pharmaceutical Product Index or NAPPI is a comprehensive database of medical products used in South Africa. Each product has a unique NAPPI code which enables electronic data interchange throughout the health care delivery chain in South Africa. \nhttp://www.pbb.co.za/Nappi-Codes.aspx',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(582,1,'AdditionalTradeItemIdentificationTypeCode','NCM','National Center for Medicines, Medical Devices and Medical Equipment Expertise','National Center for medicines, medical devices and medical equipment expertise manages the market authorisation of healthcare products in Kazakhstan - KZ',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(583,1,'AdditionalTradeItemIdentificationTypeCode','NMFA','National Medicines and Food Administration','National Medicines and Food Administration manages the market authorisation of healthcare products in Eritrea - ER',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(584,1,'AdditionalTradeItemIdentificationTypeCode','NMPB_SD','National Medicines and Poisons Board (NMPB)','National Medicines and Poisons Board (NMPB) manages the market authorisation of healthcare products in Sudan - SD',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(585,1,'AdditionalTradeItemIdentificationTypeCode','NMRA_LK','National Medicines Regulatory Authority (NMRA)','National Medicines Regulatory Authority (NMRA) manages the market authorisation of healthcare products in Sri Lanka - LK',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(586,1,'AdditionalTradeItemIdentificationTypeCode','NMRC','Namibia Medicines Regulatory Council','Namibia Medicines Regulatory Council manages the market authorisation of healthcare products in Namibia - NA',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(587,1,'AdditionalTradeItemIdentificationTypeCode','NPN','NPN','The Natural Health Product Number: Identifies the trade item as a natural health product and the number is assigned by a regulatory health organization for example the Health Canada - Natural Health Products Directorate (Health Canada).',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(588,1,'AdditionalTradeItemIdentificationTypeCode','NSN','NSN','UN/ECE Rec 24  - Fully Adopted by GS1',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(589,1,'AdditionalTradeItemIdentificationTypeCode','NUMERO_RDN','RDN','An identification number assigned by the Italian Ministry of Health to medical devices treated by the national health system',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(590,1,'AdditionalTradeItemIdentificationTypeCode','NZ_MEDICINES_TERMINOLOGY_CODE','NZ Medicines Terminology Code','For medicines used within NZ healthcare, the code assigned by NZULM (New Zealand List of Medicines). The NZ Medicines Terminology Code on the NZULM website is referred to as the SCTID (Snomed Concept ID).',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(591,1,'AdditionalTradeItemIdentificationTypeCode','PBSL','Pharmacy Board of Sierra Leone','Pharmacy Board of Sierra Leone manages the market authorisation of healthcare products in Sierra Leone - SL',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(592,1,'AdditionalTradeItemIdentificationTypeCode','PCOJ','Pharmacy Council of Jamaica (PCoJ)','Pharmacy Council of Jamaica (PCoJ) manages the market authorisation of healthcare products in Jamaica - JM',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(593,1,'AdditionalTradeItemIdentificationTypeCode','PHARMACODE_CH','Pharmacode CH','A national drug code for Switzerland assigned by e-mediat AG, Bern. The identification number based on the standard Code39 and is used in the whole Swiss healthcare market.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(594,1,'AdditionalTradeItemIdentificationTypeCode','PIRC','Pharmaceutical Inspectorate and the Registration Committee','Pharmaceutical Inspectorate and the Registration Committee manages the market authorisation of healthcare products in Suriname - SR',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(595,1,'AdditionalTradeItemIdentificationTypeCode','PLU','PLU','A number used to indicate a price look up for an existing random weight item. This is only used for items that have been assigned an industry PLU or proprietary PLU and that are utilized through a weighing system through the scales at the back or the front registers.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(596,1,'AdditionalTradeItemIdentificationTypeCode','PMPB','Pharmacy, Medicines and Poisons Board','Pharmacy, Medicines and Poisons Board manages the market authorisation of healthcare products in Malawi - MW',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(597,1,'AdditionalTradeItemIdentificationTypeCode','PPB','Pharmacy and Poisons Board','Pharmacy and Poisons Board manages the market authorisation of healthcare products in Kenya - KE',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(598,1,'AdditionalTradeItemIdentificationTypeCode','RVG','RVG','(Register Verpakte Geneesmiddelen): An identification number provided by the Institute for Drug Evaluation (College ter Beoordeling van Geneesmiddelen – CBG) in the Netherlands. This number is used as the main identification for all drugs that have been approved by the CBG for distribution within the Netherlands.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(599,1,'AdditionalTradeItemIdentificationTypeCode','RVH','RVH','(Register Verpakte Homeopatische Geneesmiddelen): An identification number provided by the Institute for Drug Evaluation (College ter Beoordeling van Geneesmiddelen – CBG) in the Netherlands. This number is used as the main identification for all homeopathic drugs that have been approved by the CBG for distribution within the Netherlands.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(600,1,'AdditionalTradeItemIdentificationTypeCode','SAN_4','SAN 4','A nationally set standard trade item number for a variable measure trade item. The SAN-4 is a four-digit number that uniquely identifies a weight trade item according to its country of origin.  This short number is incorporated into the 13 digit GTIN symbol in combination with the weight, quantity or price.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(601,1,'AdditionalTradeItemIdentificationTypeCode','SBDMA','Supreme Board for Drugs & Medical Appliances','Supreme Board for Drugs & Medical Appliances manages the market authorisation of healthcare products in Yemen - YE',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(602,1,'AdditionalTradeItemIdentificationTypeCode','SCDMTE','The Scientific Centre of Drug and Medical Technologies Expertise (SCDMTE)','The Scientific Center of Drug and Medical Technologies Expertise (SCDMTE) manages the market authorisation of healthcare products in Armenia - AM',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(603,1,'AdditionalTradeItemIdentificationTypeCode','SFDA','State Food Drug Administration (SFDA)','State Food Drug Administration (SFDA) manages the market authorisation of healthcare products in China - CN',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(604,1,'AdditionalTradeItemIdentificationTypeCode','SMDC_UA','State Service of Ukraine on Medicines and Drugs Control (SMDC)','State Service of Ukraine on Medicines and Drugs Control (SMDC) manages the market authorisation of healthcare products in Ukraine - UA',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(605,1,'AdditionalTradeItemIdentificationTypeCode','SRAMA','State Regulatory Agency for Medical Activities','State Regulatory Agency for Medical Activities manages the market authorisation of healthcare products in Georgia - GE',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(606,1,'AdditionalTradeItemIdentificationTypeCode','SUPPLIER_ASSIGNED','Supplier Assigned','The additional Trade Item Identification value populated has been developed and assigned by the party which provides service(s) and/or manufactures or otherwise has possession of the goods and consigns or makes them available in trade. This number is a base model or style number assigned to the product and may be the same for several GTINs where they are variations of each other.  For example a coffee mug with 3 GTINs one each for the brown mug, the white mug, and the black mug might all be the supplier assigned number of AB123.  Use of this value is recommended in the absence of a Model Number or Manufacturer’s Part Number. ',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(607,1,'AdditionalTradeItemIdentificationTypeCode','TFDA','Tanzania Food and Drugs Authority (TFDA)','Tanzania Food and Drugs Authority (TFDA) manages the market authorisation of healthcare products in Tanzania - TZ',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(608,1,'AdditionalTradeItemIdentificationTypeCode','WAND_NUMBER','WAND Number','The identification code assigned from the WAND (Web Assisted Notification of Devices) database.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(609,1,'AdditionalTradeItemIdentificationTypeCode','Z_INDEX','Z INDEX','An additional identification number used to identify all medical supplies and drugs in the Netherlands when managing reimbursements for the items. The Z-Index number is assigned to every product by Z-Index, which is a regulatory body in the Netherlands for the healthcare industry.',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(610,1,'AdditionalTradeItemIdentificationTypeCode','ZAMRA','Zambia Medicines Regulatory Authority (ZAMRA)','Zambia Medicines Regulatory Authority (ZAMRA) manages the market authorisation of healthcare products in Zambia - ZM',NULL,'6',1,'additionaltradeitemidentificationtypecode'),(611,1,'TemperatureQualifierCode','DELIVERY_TO_DISTRIBUTION_CENTRE','Delivery To Distribution Centre','Trade Item is in transport to the distribution center.',NULL,'2',1,'temperaturequalifiercode'),(612,1,'TemperatureQualifierCode','DELIVERY_TO_MARKET','Delivery To Market','Trade Item is in transport to market.',NULL,'2',1,'temperaturequalifiercode'),(613,1,'TemperatureQualifierCode','INLET_TEMPERATURE','Inlet Temperature','Indicates the maximum inlet temperature of a gas or fluid into an electrical or mechanical device for e.g. an electric pressure washer. Outside this maximum inlet temperature the device may fail.',NULL,'2',1,'temperaturequalifiercode'),(614,1,'TemperatureQualifierCode','OPERATING_TEMPERATURE','Operating Temperature','Indicates the maximum operating temperature. An operating temperature is the temperature at which an electrical or mechanical device operates effectively. The device will operate effectively within a specified temperature range which varies based on the device function and application context, and ranges from the minimum operating temperature to the maximum operating temperature (or peak operating temperature). Outside this range of safe operating temperatures the device may fail.',NULL,'2',1,'temperaturequalifiercode'),(615,1,'TemperatureQualifierCode','STORAGE_AFTER_OPENING','Storage After Opening ','Specifies the temperature the product is to be maintained at after its seal has been broken and the product has been exposed to the elements.',NULL,'2',1,'temperaturequalifiercode'),(616,1,'TemperatureQualifierCode','STORAGE_AFTER_OVERWRAP','Storage After Removing Overwrap','Specifies the temperature the product is to be maintained at  after  removing a product’s protective overwrap or moisture barrier.',NULL,'2',1,'temperaturequalifiercode'),(617,1,'TemperatureQualifierCode','STORAGE_AFTER_RECONSTITUTION','Storage After Reconstitution','Specifies the temperature the product is to be maintained at after adding liquid to mix or dilute the product.',NULL,'2',1,'temperaturequalifiercode'),(618,1,'TemperatureQualifierCode','STORAGE_HANDLING','Storage and Handling','Trade Item is being stored or handled.',NULL,'2',1,'temperaturequalifiercode'),(619,1,'TemperatureQualifierCode','TRANSPORTATION','Transportation','Trade item is in process of being transported in the supply chain.',NULL,'2',1,'temperaturequalifiercode'),(620,1,'TemperatureQualifierCode','WORKING_TEMPERATURE','Working Temperature','Indicates the maximal working temperature or outside temperature where an electrical or mechanical device will operate effectively.',NULL,'2',1,'temperaturequalifiercode'),(621,1,'ReferencedFileTypeCode','360_DEGREE_IMAGE','360 Degree Image','Allows x-axis interactive rotation of product via website.',NULL,'5',1,'referencedfiletypecode'),(622,1,'ReferencedFileTypeCode','ASSEMBLY_INSTRUCTIONS','Assembly Instructions','Link to a file the explains how to assemble (put together) the trade item.',NULL,'5',1,'referencedfiletypecode'),(623,1,'ReferencedFileTypeCode','AUDIO','Audio','Link to a file containing an audio clip which is relevant to the product. Examples are commercials, or instructional/ how to use audio files.',NULL,'5',1,'referencedfiletypecode'),(624,1,'ReferencedFileTypeCode','CERTIFICATION','Certification','Document which contains a special certification by a third party (e.g. International Food Standard [IFS], QS-Approval Mark for meat product, sausage, fruit, vegetables and potatoes or bio audits).',NULL,'5',1,'referencedfiletypecode'),(625,1,'ReferencedFileTypeCode','CHEMICAL_ASSESSMENT_SUMMARY','Chemical Assessment Summary','Link to a file containing the chemical ingredient information sent to the supplier from a third party as a result of the assessment.',NULL,'5',1,'referencedfiletypecode'),(626,1,'ReferencedFileTypeCode','CHEMICAL_SAFETY_REPORT','Chemical Safety Report','Link to the file containing a report detailing the risks arising from the manufacture and/or use of a substance and to ensure that they are adequately controlled.',NULL,'5',1,'referencedfiletypecode'),(627,1,'ReferencedFileTypeCode','CHILD_NUTRITION_LABEL','Child Nutrition Label','Link to a file containing the Child Nutrition Label as formatted according to regulations and rules of an appropriate regulatory body for the target market.',NULL,'5',1,'referencedfiletypecode'),(628,1,'ReferencedFileTypeCode','CONSUMER_HANDLING_AND_STORAGE','Consumer Handling and Storage','Link to a website, file, or image containing the manufacturer\'s recommendations for how the consumer or end user should store and handle the product.',NULL,'5',1,'referencedfiletypecode'),(629,1,'ReferencedFileTypeCode','CROSSSECTION_VIEW','Crosssection View',' A picture of a trade item with a cut away vertical plane removed (e.g. Cross-section of a Tire revealing steel belts and tire tread detail).',NULL,'5',1,'referencedfiletypecode'),(630,1,'ReferencedFileTypeCode','DIET_CERTIFICATE','Diet Certificate','Link to a website or file containing a diet certificate granted to the product',NULL,'5',1,'referencedfiletypecode'),(631,1,'ReferencedFileTypeCode','DOCUMENT','Document','Link to a document or text file containing product information. Examples of this type could be an instruction manual, assembly guide, or warranty document.',NULL,'5',1,'referencedfiletypecode'),(632,1,'ReferencedFileTypeCode','DOP_SHEET','Dop Sheet','Link to a file containing the product\'s Declaration of Performance Sheet (DOP). This file can be either an image or a document.',NULL,'5',1,'referencedfiletypecode'),(633,1,'ReferencedFileTypeCode','DRUG_FACT_LABEL','Drug Fact Label','The file link is to a drug fact panel of the trade item. A drug fact label usually contains such items as active ingredients, uses, warnings, purpose, directions, etc.',NULL,'5',1,'referencedfiletypecode'),(634,1,'ReferencedFileTypeCode','ENERGY_LABEL','Energy Label','Link to the energy label for a trade item.  On 19 May 2010, the EU adopted the Directive 2010/30/EU on energy labels. Energy labels help consumers choosing products which save energy and thus money. They also provide incentives for the industry to develop and invest in energy efficient product design. They are found on a selection of white goods and other products and are designed to help customers see how energy efficient a model is before they buy.',NULL,'5',1,'referencedfiletypecode'),(635,1,'ReferencedFileTypeCode','GROUP_CHARACTERISTIC_SHEET','Group Characteristic Sheet',NULL,NULL,'5',1,'referencedfiletypecode'),(636,1,'ReferencedFileTypeCode','HAZARDOUS_SUBSTANCES_DATA','Hazardous Substances Data','Link to a file where to locate the ‘out of network data’ additional data concerning the control of substances can be found.',NULL,'5',1,'referencedfiletypecode'),(637,1,'ReferencedFileTypeCode','IFU','IFU','Link to a file containing the Instructions For Use (IFU). This type of file is primarily used in conjunction with ingestible products, regardless of species.',NULL,'5',1,'referencedfiletypecode'),(638,1,'ReferencedFileTypeCode','INTERNAL_VIEW','Internal View','The picture of the inside of a trade item mainly used for non food products (e.g., The inside of a refrigerator or the inside of a suitcase. ',NULL,'5',1,'referencedfiletypecode'),(639,1,'ReferencedFileTypeCode','LOGO','Logo','Link to a file containing the Manufacturer or Brand Logo(s) associated with the product.',NULL,'5',1,'referencedfiletypecode'),(640,1,'ReferencedFileTypeCode','MARKETING_INFORMATION','Marketing Information','Link to a file with product information associated with selling a product or service.',NULL,'5',1,'referencedfiletypecode'),(641,1,'ReferencedFileTypeCode','MATERIAL_SAMPLES','Material Samples','URL to website, images that the potential material, swatches, finishes the trade item might be available in.\n',NULL,'5',1,'referencedfiletypecode'),(642,1,'ReferencedFileTypeCode','MOBILE_DEVICE_IMAGE','Mobile Device Image','Trade Item image that represents the image the manufacturer supplies to the consumer for mobile device applications',NULL,'5',1,'referencedfiletypecode'),(643,1,'ReferencedFileTypeCode','NUTRITION_FACT_LABEL','Nutrition Fact Label','Link to a file containing a visual representation of the product label containing the nutritional information.',NULL,'5',1,'referencedfiletypecode'),(644,1,'ReferencedFileTypeCode','ORGANIC_CERTIFICATE','Organic Certificate','Link to a website or file containing an organic certificate granted to the product.',NULL,'5',1,'referencedfiletypecode'),(645,1,'ReferencedFileTypeCode','OTHER_EXTERNAL_INFORMATION','Other External Information','Link to a file containing product information of an unspecified type.',NULL,'5',1,'referencedfiletypecode'),(646,1,'ReferencedFileTypeCode','OUT_OF_PACKAGE_IMAGE','Out of Package Image','Link to an image of an item out of its packaging and, if necessary, assembled ready for use by the end user. This type of file is subject the current version of the GDSN Product Image Specification Standard.',NULL,'5',1,'referencedfiletypecode'),(647,1,'ReferencedFileTypeCode','PACKAGING_ARTWORK','Packaging Artwork','Design files for packaging artwork for example Adobe source files.',NULL,'5',1,'referencedfiletypecode'),(648,1,'ReferencedFileTypeCode','PLANOGRAM','Planogram','Link to a file illustrating how and where retail products should be displayed.',NULL,'5',1,'referencedfiletypecode'),(649,1,'ReferencedFileTypeCode','PRODUCT_FORMULATION_STATEMENT','Product Formulation Statement','Link to a file containing the Product Formulation Statement, in lieu of a Child Nutrition Label, as formatted according to regulations and rules of an appropriate regulatory body for the target market.',NULL,'5',1,'referencedfiletypecode'),(650,1,'ReferencedFileTypeCode','PRODUCT_IMAGE','Product Image','Link to a file containing a visual representation of the product.',NULL,'5',1,'referencedfiletypecode'),(651,1,'ReferencedFileTypeCode','PRODUCT_LABEL_IMAGE','Product Label Image','Link to a file containing a visual representation of the product label.',NULL,'5',1,'referencedfiletypecode'),(652,1,'ReferencedFileTypeCode','PRODUCT_WEBSITE','Product Website','Link to a website containing product specific information. Examples of this could be a link to a website dedicated to the product or a link to the area within the manufacturer or brand owner website that contains the product information',NULL,'5',1,'referencedfiletypecode'),(653,1,'ReferencedFileTypeCode','QR_CODE','Link to QR Code','Link to a QR code URL/URI.',NULL,'5',1,'referencedfiletypecode'),(654,1,'ReferencedFileTypeCode','QUALITY_CONTROL_PLAN','Quality Control Plan','Document which detailed information about the quantity of laboratory/analytical tests and the evaluated parameters.',NULL,'5',1,'referencedfiletypecode'),(655,1,'ReferencedFileTypeCode','RECIPE_WEBSITE','Recipe Website','Link to a website containing recipes associated with the product',NULL,'5',1,'referencedfiletypecode'),(656,1,'ReferencedFileTypeCode','REGULATORY_INSPECTION_AUDIT','Regulatory Inspection Audit','Inspection report of the inspections. For example foodstuffs, pharmaceuticals and other types of products that are regulated.',NULL,'5',1,'referencedfiletypecode'),(657,1,'ReferencedFileTypeCode','RISK_ANALYSIS_DOCUMENT','Risk Analysis Document','Document which describes how the supplier assured the quality control of the end products or during the production process. The process can be a supplier internal control system, a simple kind of risk analysis or systematic preventive approach according Hazard Analysis and Critical Control Points (HACCP).',NULL,'5',1,'referencedfiletypecode'),(658,1,'ReferencedFileTypeCode','SAFETY_DATA_SHEET','Safety Data Sheet','Link to a file containing the product\'s Safety Data Sheet (SDS). This file can be either an image or a document',NULL,'5',1,'referencedfiletypecode'),(659,1,'ReferencedFileTypeCode','SAFETY_SUMMARY_SHEET','Safety Summary Sheet','A link to a summary sheet document that is available to workers to understand how to deal with chemicals in an emergency situation.',NULL,'5',1,'referencedfiletypecode'),(660,1,'ReferencedFileTypeCode','SAMPLE_SHIPPING_ORDER','Sample Shipping Order','Document is a sample shipping order. A sample shipping order isn´t needed for every item (GTIN), but a shipping order can differ from GTIN to GTIN. E.g. in case an item is an organic product the sample shipping order needs to contain the organic product origin number according article 31 of the implementing regulations EG Nr. 889/2008. For non-organic items this information isn´t needed.    ',NULL,'5',1,'referencedfiletypecode'),(661,1,'ReferencedFileTypeCode','SUMMARY_OF_PRODUCT_CHARACTERISTICS','Summary of Product Characteristics','Specific document required before any medicinal product or biocidal product is authorized for marketing.  Example European Commission',NULL,'5',1,'referencedfiletypecode'),(662,1,'ReferencedFileTypeCode','TESTING_METHODOLOGY_RESULTS','Testing Methodology Results','Document which contains microbiological and physico-chemical findings of the product which are observed during product testing.',NULL,'5',1,'referencedfiletypecode'),(663,1,'ReferencedFileTypeCode','TRADE_ITEM_DESCRIPTION','Trade Item Description','Identifies the reference to an external description of a Trade Item. The link (e.g. URL) to the external description. will be in the appropriate attribute',NULL,'5',1,'referencedfiletypecode'),(664,1,'ReferencedFileTypeCode','TRADE_ITEM_IMAGE_WITH_DIMENSIONS','Trade Item Image With Dimensions','Link to a website, file, or image containing the product\'s image with its dimensions. This especially important for built-in products as ovens and fridges. Ex : http://www.docstoc.com/docs/125126778/GSS-GEW-Food-Savers-Food-Storage-Containers.',NULL,'5',1,'referencedfiletypecode'),(665,1,'ReferencedFileTypeCode','VIDEO','Video','Link to a file containing a video clip which is relevant to the product. Examples are commercials, trailers, or instructional/ how to use video files.',NULL,'5',1,'referencedfiletypecode'),(666,1,'ReferencedFileTypeCode','WARRANTY_INFORMATION','Warranty Information','Link to a file with information associated with any guarantee given by a company stating that a product is reliable and free from known defects and that the seller will, without charge, repair or replace defective parts within a given time limit and under certain conditions.',NULL,'5',1,'referencedfiletypecode'),(667,1,'ReferencedFileTypeCode','WEBSITE','Website','Link to a website containing product or manufacturer information.',NULL,'5',1,'referencedfiletypecode'),(668,1,'ReferencedFileTypeCode','ZOOM_VIEW','Zoom View','A picture of a portion of a trade item (e.g., the wheels of a suitcase or the ingredients list of a food trade item). ',NULL,'5',1,'referencedfiletypecode'),(669,1,'GDSNMeasurementUnitCode','B37','Kilogram Force','The gravitational force of a kilogram weight or a one-kilogram mass multiplied by the acceleration of standard Earth gravity, equal to 9.8 newtons.',NULL,'7',1,'gdsnmeasurementunitcode'),(670,1,'GDSNMeasurementUnitCode','B47','Kilonewton','1000 Newtons or amount needed to accelerate 1 kilogram of mass at the rate of 1 metre per second squared multiplied by 1000 (Used to measure force of an object where the value exceeds 1000 newtons).',NULL,'7',1,'gdsnmeasurementunitcode'),(671,1,'GDSNMeasurementUnitCode','C16','Millimetre Per Second','The number of millimetre per second the trade item or part of the trade item moves.',NULL,'7',1,'gdsnmeasurementunitcode'),(672,1,'GDSNMeasurementUnitCode','X_HIN','Hundredths of an Inch','One Hundredth of an inch or 0.01. (Usage- Measurements of Papers, Films, Circuit boards and the like)',NULL,'7',1,'gdsnmeasurementunitcode'),(673,1,'GDSNMeasurementUnitCode','1N','Count','Count',NULL,'7',1,'gdsnmeasurementunitcode'),(674,1,'GDSNMeasurementUnitCode','23','Grams Per Cubic Centimetre','Grams Per Cubic Centimetre',NULL,'7',1,'gdsnmeasurementunitcode'),(675,1,'GDSNMeasurementUnitCode','28','Kilogram per square metre','A unit of pressure equal to 9.80665*10-05 Bar',NULL,'7',1,'gdsnmeasurementunitcode'),(676,1,'GDSNMeasurementUnitCode','2L','Cubic Foot Per Minute','Cubic foot per minute',NULL,'7',1,'gdsnmeasurementunitcode'),(677,1,'GDSNMeasurementUnitCode','2M','Centimetre Per Second','The number of centimetre per second the trade item or part of the trade item moves.',NULL,'7',1,'gdsnmeasurementunitcode'),(678,1,'GDSNMeasurementUnitCode','2N','Decibel','A measurement for sound in air and other gases, relative to 20 micropascals (μPa) = 2×10−5 Pa, the quietest sound a human can hear. This is roughly the sound of a mosquito flying 3 metres away. This is often abbreviated to just \"dB\"; however the correct abbreviation is dB(SPL), indicating decibel for Sound Pressure Level.',NULL,'7',1,'gdsnmeasurementunitcode'),(679,1,'GDSNMeasurementUnitCode','2P','Kilobyte','A unit of information equal to 103 (1000) bytes.',NULL,'7',1,'gdsnmeasurementunitcode'),(680,1,'GDSNMeasurementUnitCode','2Q','Kilo Becquerel','kBq is 103 Bq',NULL,'7',1,'gdsnmeasurementunitcode'),(681,1,'GDSNMeasurementUnitCode','2X','Metre Per Minute','Metre Per Minute',NULL,'7',1,'gdsnmeasurementunitcode'),(682,1,'GDSNMeasurementUnitCode','4G','Microlitre','A microlitre is one millionth of a litre',NULL,'7',1,'gdsnmeasurementunitcode'),(683,1,'GDSNMeasurementUnitCode','4H','Micrometre','A micrometre is one millionth of a metre, also termed Micron.',NULL,'7',1,'gdsnmeasurementunitcode'),(684,1,'GDSNMeasurementUnitCode','4L','Megabyte','A unit of information equal to 10 (1000000) bytes.',NULL,'7',1,'gdsnmeasurementunitcode'),(685,1,'GDSNMeasurementUnitCode','4N','Megabecquerel','Megabecquerel: 106 Bq1 Bq is defined as the activity of a quantity of radioactive material in which one nucleus decays per second.',NULL,'7',1,'gdsnmeasurementunitcode'),(686,1,'GDSNMeasurementUnitCode','58','Net kilogram','A unit of mass defining the total number of kilograms after deductions.',NULL,'7',1,'gdsnmeasurementunitcode'),(687,1,'GDSNMeasurementUnitCode','59','Part per million','A unit of proportion equal to 10-6 (ppm).',NULL,'7',1,'gdsnmeasurementunitcode'),(688,1,'GDSNMeasurementUnitCode','5B','Batch','A unit of count defining the number of batches (batch: quantity of material produced in one operation or number of animals or persons coming at once).',NULL,'7',1,'gdsnmeasurementunitcode'),(689,1,'GDSNMeasurementUnitCode','64','Pound per square inch - Gauge','Psig (pound-force per square inch gauge) is a unit of pressure relative to the surrounding atmosphere. At sea level, Earth\'s atmosphere actually exerts a pressure of 14.7 psi. Humans do not feel this pressure because internal pressure of liquid in their bodies matches the external pressure. If a pressure gauge is calibrated to read zero in space, then at sea level on Earth it would read 14.7 psi. Thus a reading of 30 psig, on Earth, on a tire gauge represents an absolute pressure of 44.7 psi (lb/in2).',NULL,'7',1,'gdsnmeasurementunitcode'),(690,1,'GDSNMeasurementUnitCode','80','Pound per square inch - Absolute','Psia (pound-force per square inch absolute)is a unit of pressure pressure relative to a vacuum (such as that in space).At sea level, Earth\'s atmosphere actually exerts a pressure of 14.7 psi. Humans do not feel this pressure because internal pressure of liquid in their bodies matches the external pressure. If a pressure gauge is calibrated to read zero in space, then at sea level on Earth it would read 14.7 psi. Thus a reading of 30 psig, on Earth, on a tire gauge represents an absolute pressure of 44.7 psi (lb/in2).',NULL,'7',1,'gdsnmeasurementunitcode'),(691,1,'GDSNMeasurementUnitCode','A11','Angstrom','A unit of length equal to one hundred-millionth of a centimetre, 10–10 metre, used mainly to express wavelengths and interatomic distances.',NULL,'7',1,'gdsnmeasurementunitcode'),(692,1,'GDSNMeasurementUnitCode','A24','Candela per Square Metre','Candela per Square Metre',NULL,'7',1,'gdsnmeasurementunitcode'),(693,1,'GDSNMeasurementUnitCode','A43','Deadweight Tonnage','A unit of mass defining the difference between the weight of a ship when completely empty and its weight when completely loaded, expressed as the number of tons.',NULL,'7',1,'gdsnmeasurementunitcode'),(694,1,'GDSNMeasurementUnitCode','A71','Femtometre','Femtometre- a quadrillionth of a metre (10 to the negative 15th power)  ',NULL,'7',1,'gdsnmeasurementunitcode'),(695,1,'GDSNMeasurementUnitCode','A86','Gigahertz','A unit of frenquecy equal to 109 Hertz',NULL,'7',1,'gdsnmeasurementunitcode'),(696,1,'GDSNMeasurementUnitCode','AD','Byte','A unit of information equal to 8 bits.',NULL,'7',1,'gdsnmeasurementunitcode'),(697,1,'GDSNMeasurementUnitCode','AMH','Ampere Hour','A unit of electric charge defining the amount of charge accumulated by a steady flow of one ampere for one hour.',NULL,'7',1,'gdsnmeasurementunitcode'),(698,1,'GDSNMeasurementUnitCode','AMP','Ampere','Ampere',NULL,'7',1,'gdsnmeasurementunitcode'),(699,1,'GDSNMeasurementUnitCode','ANN','Year','Unit of time equal to 365,25 days.',NULL,'7',1,'gdsnmeasurementunitcode'),(700,1,'GDSNMeasurementUnitCode','APZ','Troy ounce or apothecary ounce','The troy ounce is a unit of imperial measure. In the present day it is most commonly used to gauge the weight and therefore the price of precious metals. One troy ounce equals 480 grains or 31.1035 grams.',NULL,'7',1,'gdsnmeasurementunitcode'),(701,1,'GDSNMeasurementUnitCode','AS','Assortment','A unit of count defining the number of assortments (assortment: set of items grouped in a mixed collection).',NULL,'7',1,'gdsnmeasurementunitcode'),(702,1,'GDSNMeasurementUnitCode','ATM','Standard Atmosphere','Standard Atmosphere',NULL,'7',1,'gdsnmeasurementunitcode'),(703,1,'GDSNMeasurementUnitCode','ATT','Technical Atmosphere','Technical Atmosphere',NULL,'7',1,'gdsnmeasurementunitcode'),(704,1,'GDSNMeasurementUnitCode','AWG','Gauge','Gauge- A number referring to the outer diameter of hypodermic or suture needles. Smaller gauge numbers indicate larger outer diameters. Inner diameter depends on both gauge and wall thickness. An increasing needle-gauge size corresponds to a smaller diameter needle. This is contrary to French Gauge where an increasing gauge size corresponds to a larger external diameter.',NULL,'7',1,'gdsnmeasurementunitcode'),(705,1,'GDSNMeasurementUnitCode','AXU','Anti XA Unit','A unit of measure for blood potency. Units for the anti XA activity which is a measure to the anti coagulating effect at low molecular heparins.',NULL,'7',1,'gdsnmeasurementunitcode'),(706,1,'GDSNMeasurementUnitCode','B10','Bit per second','In telecommunications and computing, bitrate (sometimes written bit rate, data rate or as a variable R or fb) is the number of bits that are conveyed or processed per unit of time.The bit rate is quantified using the bits per second (bit/s or bps) unit.',NULL,'7',1,'gdsnmeasurementunitcode'),(707,1,'GDSNMeasurementUnitCode','B60','Lumens per Square Meter','Lumens per Square Meter',NULL,'7',1,'gdsnmeasurementunitcode'),(708,1,'GDSNMeasurementUnitCode','B61','Lumens Per Watt','The number of Lumens expressed per watt.',NULL,'7',1,'gdsnmeasurementunitcode'),(709,1,'GDSNMeasurementUnitCode','B62','Lumen Seconds','Lumen seconds is the SI derived unit of luminous energy. It is based on the lumen, the SI unit of luminous flux, and the second, the SI base unit of time.\nThe lumen second is sometimes called the Talbot (symbol T). ',NULL,'7',1,'gdsnmeasurementunitcode'),(710,1,'GDSNMeasurementUnitCode','B64','Lux Seconds','Exposure is measured in lux seconds, and can be computed from exposure value (EV) and scene luminance in a specified region.',NULL,'7',1,'gdsnmeasurementunitcode'),(711,1,'GDSNMeasurementUnitCode','BAR','Bar (unit of pressure)','The bar is widely used in descriptions of pressure; 1 bar = 100 kilopascals 0.987 atmospheres.',NULL,'7',1,'gdsnmeasurementunitcode'),(712,1,'GDSNMeasurementUnitCode','BB','Base box','A unit of area of 112 sheets of tin mil products (tin plate, tin free steel or black plate) 14 by 20 inches, or 31,360 square inches.',NULL,'7',1,'gdsnmeasurementunitcode'),(713,1,'GDSNMeasurementUnitCode','BFT','Board Foot','A specialized unit of measure for the volume of rough lumber (before drying and planing with no adjustments) or planed/surfaced lumber. It is the volume of a one-foot length of a board one foot wide and one inch thick. Some countries utilize the synonym super foot or superficial foot.',NULL,'7',1,'gdsnmeasurementunitcode'),(714,1,'GDSNMeasurementUnitCode','BLL','Barrel US','There are varying standards for barrel for some specific commodities, including 31 gal for beer, 40 gal for whiskey or kerosene, and 42 gal for petroleum. The general standard for liquids is 31.5 gal or half a hogshead; the general standard for dry contents is 7,056 Cubic Inches.',NULL,'7',1,'gdsnmeasurementunitcode'),(715,1,'GDSNMeasurementUnitCode','BP','Hundred board foot','A unit of volume equal to one hundred board foot.',NULL,'7',1,'gdsnmeasurementunitcode'),(716,1,'GDSNMeasurementUnitCode','BPM','Beats Per Minute','Beats Per Minute',NULL,'7',1,'gdsnmeasurementunitcode'),(717,1,'GDSNMeasurementUnitCode','BQL','Becquerel','The becquerel (symbol Bq) is the SI derived unit of radioactivity. One Bq is defined as the activity of a quantity of radioactive material in which one nucleus decays per second. SI uses the becquerel rather than the second for the unit of activity measure to avoid dangerous mistakes: a measurement in becquerels is proportional to activity, and thus a more dangerous source of radiation gives a higher reading. A measurement in seconds is inversely proportional.',NULL,'7',1,'gdsnmeasurementunitcode'),(718,1,'GDSNMeasurementUnitCode','BTU','British thermal unit','The British thermal unit (BTU or Btu) is a traditional unit of energy. It is approximately the amount of energy needed to heat one pound of water one degree Fahrenheit. One Btu is equal to about 1.06 kilojoules. It is used in the power, steam generation, heating and air conditioning industries.',NULL,'7',1,'gdsnmeasurementunitcode'),(719,1,'GDSNMeasurementUnitCode','BUA','Bushel (US)','A bushel is an imperial and U.S. customary unit of dry volume, equivalent in each of these systems to 4 pecks or 8 gallons. It is used for volumes of dry commodities (not liquids), most often in agriculture',NULL,'7',1,'gdsnmeasurementunitcode'),(720,1,'GDSNMeasurementUnitCode','BUI','Bushel (UK)','A bushel is an imperial and U.S. customary unit of dry volume, equivalent in each of these systems to 4 pecks or 8 gallons. It is used for volumes of dry commodities (not liquids), most often in agriculture',NULL,'7',1,'gdsnmeasurementunitcode'),(721,1,'GDSNMeasurementUnitCode','C18','Millimole','a millimole is one thousandth of a mole.',NULL,'7',1,'gdsnmeasurementunitcode'),(722,1,'GDSNMeasurementUnitCode','C26','Millisecond','A millisecond (from milli- and second; abbreviation: ms) is a thousandth (1/1000) of a second.',NULL,'7',1,'gdsnmeasurementunitcode'),(723,1,'GDSNMeasurementUnitCode','C34','Mole','The mole (symbol mol) is the SI base unit of amount of substance; one of a few units used to measure this physical quantity.A mole will possess mass exactly equal to the substance\'s molecular or atomic weight in grams. That is to say, a substance\'s atomic or molecular mass in atomic mass units is the same as its molar mass in grams. Because of this, one can measure the number of moles in a pure substance by weighing it and comparing the result to its molecular or atomic weight',NULL,'7',1,'gdsnmeasurementunitcode'),(724,1,'GDSNMeasurementUnitCode','C45','Nanometre','Nanometre- a billionth of a metre (10 to the negative 9th power) ',NULL,'7',1,'gdsnmeasurementunitcode'),(725,1,'GDSNMeasurementUnitCode','C52','Picometre','Picometre- a trillionth of a metre (10 to the negative 12th power) ',NULL,'7',1,'gdsnmeasurementunitcode'),(726,1,'GDSNMeasurementUnitCode','C75','Picowatt','Picowatt is a derived metric SI (System International) measurement unit of power.  The picowatt is equal to one trillionth of a watt (10-12W).\n',NULL,'7',1,'gdsnmeasurementunitcode'),(727,1,'GDSNMeasurementUnitCode','CEL','Degree Celsius','Celsius (also historically known as centigrade) is a temperature scale, the freezing point of water is 0 degrees Celsius (°C) and the boiling point 100 °C (at standard atmospheric pressure), placing the boiling and freezing points of water exactly 100 degrees apart.',NULL,'7',1,'gdsnmeasurementunitcode'),(728,1,'GDSNMeasurementUnitCode','CFU','Colony Forming Units ','Colony Forming Units: is a rough estimate of the number of viable bacteria or fungal cells in a sample.',NULL,'7',1,'gdsnmeasurementunitcode'),(729,1,'GDSNMeasurementUnitCode','CG','Card','A unit of count defining the number of units of card (card: thick stiff paper or cardboard).',NULL,'7',1,'gdsnmeasurementunitcode'),(730,1,'GDSNMeasurementUnitCode','CGM','Centigram','A centigram is one hundredth (1/100) of a gram',NULL,'7',1,'gdsnmeasurementunitcode'),(731,1,'GDSNMeasurementUnitCode','CLT','Centilitre','A centilitre is one hundredth (1/100) of a litre',NULL,'7',1,'gdsnmeasurementunitcode'),(732,1,'GDSNMeasurementUnitCode','CMK','Square centimetre','A square centimetre is an area of a square whose sides are exactly 1 centimetre in length.',NULL,'7',1,'gdsnmeasurementunitcode'),(733,1,'GDSNMeasurementUnitCode','CMQ','Cubic centimetre','A cubic centimetre is the volume of a cube of side length one centimetre (0.01 m) equal to a millilitre.',NULL,'7',1,'gdsnmeasurementunitcode'),(734,1,'GDSNMeasurementUnitCode','CMT','Centimetre','A centimetre is equal to one hundredth of a metre.',NULL,'7',1,'gdsnmeasurementunitcode'),(735,1,'GDSNMeasurementUnitCode','CTM','Metric Carat','Metric Carat',NULL,'7',1,'gdsnmeasurementunitcode'),(736,1,'GDSNMeasurementUnitCode','CWA','Hundred pound (cwt) / hundred weight (US)','A unit of weight in the U.S. Customary System equal to 100 pounds (45.36 kilograms); also called cental.',NULL,'7',1,'gdsnmeasurementunitcode'),(737,1,'GDSNMeasurementUnitCode','CWI','Hundred weight (UK)','A unit of weight in the British Imperial System equal to 112 pounds (50.80 kilograms); also called quintal.',NULL,'7',1,'gdsnmeasurementunitcode'),(738,1,'GDSNMeasurementUnitCode','D03','Kilowatt / hour','A unit of accumulated energy of a thousand watts over a period of one hour.',NULL,'7',1,'gdsnmeasurementunitcode'),(739,1,'GDSNMeasurementUnitCode','D19','Square metre kelvin per watt','Square metre kelvin per watt .The definition is the thermal resistance (or Rd value) of the material, which is measured by the thickness of the material layer divided by the thermal conductivity of the material. and is expressed in m²K/W. ',NULL,'7',1,'gdsnmeasurementunitcode'),(740,1,'GDSNMeasurementUnitCode','D29','Terahertz','A unit of frenquecy equal to 1012 Hertz',NULL,'7',1,'gdsnmeasurementunitcode'),(741,1,'GDSNMeasurementUnitCode','D30','Terajoule','A terajoule is 1012 joules',NULL,'7',1,'gdsnmeasurementunitcode'),(742,1,'GDSNMeasurementUnitCode','D32','Terawatt hour','A terawatt hour is 109 * kilowat hour or 3.6 petajoules.',NULL,'7',1,'gdsnmeasurementunitcode'),(743,1,'GDSNMeasurementUnitCode','D40','Thousand Litre','References SI system of units of measure',NULL,'7',1,'gdsnmeasurementunitcode'),(744,1,'GDSNMeasurementUnitCode','D43','Atomic Mass Units (AMU)','Atomic Mass Units',NULL,'7',1,'gdsnmeasurementunitcode'),(745,1,'GDSNMeasurementUnitCode','D5','Kilogram per square centimetre','A kilogram-force per square centimeter (kgf/cm2), often just kilogram per square centimeter (kg/cm2), or kilopond per square centimeter is a unit of pressure using metric units. Its use is now deprecated; it is not a part of the International System of Units (SI), the modern metric system. The unit is similar to the English unit psi (lbf/in2).',NULL,'7',1,'gdsnmeasurementunitcode'),(746,1,'GDSNMeasurementUnitCode','D55','Heat Transfer Coefficient ','Heat Transfer Coefficient ',NULL,'7',1,'gdsnmeasurementunitcode'),(747,1,'GDSNMeasurementUnitCode','D63','Book','A unit of count defining the number of books (book: set of items bound together or written document of a material whole).',NULL,'7',1,'gdsnmeasurementunitcode'),(748,1,'GDSNMeasurementUnitCode','D70','Calorie - International Table (IT)','A calorie is 1/100 of the amount of energy required to warm one gram of air-free water from 0 °C to 100 °C at standard atmospheric pressure; this is about 4.190 J. Its use is archaic, having been replaced by the SI unit of energy, the joule. However, in many countries it remains in common use as a unit of food energy. In the context of nutrition, and especially food labelling, the calorie is approximately equal to 4.1868 joules (J), and energy values are normally quoted in kilojoules (kJ) and kilocalories (kcal). This code is being deprecated. Use code E14 Kilocalorie to express food calories.',NULL,'7',1,'gdsnmeasurementunitcode'),(749,1,'GDSNMeasurementUnitCode','DAY','Days','A day is one three hundreds and sixty fifth (1/365) of a year',NULL,'7',1,'gdsnmeasurementunitcode'),(750,1,'GDSNMeasurementUnitCode','DD','Degree (Unit of Angel)','A measurement of plane angle, representing 1⁄360 of a full rotation; one degree is equivalent to π/180 radians.',NULL,'7',1,'gdsnmeasurementunitcode'),(751,1,'GDSNMeasurementUnitCode','DG','Decigram','A decigram is one tenth (1/10) of a gram.',NULL,'7',1,'gdsnmeasurementunitcode'),(752,1,'GDSNMeasurementUnitCode','DLT','Decilitre','A decilitre is one tenth (1/10) of a litre.',NULL,'7',1,'gdsnmeasurementunitcode'),(753,1,'GDSNMeasurementUnitCode','DMK','Square decimetre','A square deciimetre is an area of a square whose sides are exactly 1 deciimetre in length.',NULL,'7',1,'gdsnmeasurementunitcode'),(754,1,'GDSNMeasurementUnitCode','DMQ','Cubic decimetre','A cubic decimetre is the volume of a cube of side length one decimetre (0.1 m)',NULL,'7',1,'gdsnmeasurementunitcode'),(755,1,'GDSNMeasurementUnitCode','DMT','Decimetre','A decimetre is equal to one tenth of a metre.',NULL,'7',1,'gdsnmeasurementunitcode'),(756,1,'GDSNMeasurementUnitCode','DRA','Dram (US)','The dram (archaic spelling drachm) was historically both a coin and a weight. Currently it is both a small mass in the Apothecaries\' system of weights and a small unit of volume. This unit is called more correctly fluid dram or in contraction also fluidram. The term also refers to the fluid dram, a measure of capacity equal 1⁄8 of a fluid ounce, which means it is exactly equal to 3.696 691 195 312 5 mL in the United States.',NULL,'7',1,'gdsnmeasurementunitcode'),(757,1,'GDSNMeasurementUnitCode','DRI','Dram (UK)','The dram (archaic spelling drachm) was historically both a coin and a weight. Currently it is both a small mass in the Apothecaries\' system of weights and a small unit of volume. This unit is called more correctly fluid dram or in contraction also fluidram. The fluid dram is defined as 1⁄8 of a fluid ounce, which means it is exactly equal to 3.551 632 812 500 0 mL in the Commonwealth and Ireland. In England dram came to mean a small draught of cordial or alcohol; hence the term dram-house for the taverns where one could purchase a dram.',NULL,'7',1,'gdsnmeasurementunitcode'),(758,1,'GDSNMeasurementUnitCode','DZN','Dozen','A unit of count defining the number of units in multiples of 12.',NULL,'7',1,'gdsnmeasurementunitcode'),(759,1,'GDSNMeasurementUnitCode','E09','Milliampere hour','Milliampere hour',NULL,'7',1,'gdsnmeasurementunitcode'),(760,1,'GDSNMeasurementUnitCode','E14','Kilocalorie (international table)','A unit of energy equal to 1000 calories.',NULL,'7',1,'gdsnmeasurementunitcode'),(761,1,'GDSNMeasurementUnitCode','E27','Dose','A unit of count defining the number of doses (dose: a definite quantity of a medicine or drug).',NULL,'7',1,'gdsnmeasurementunitcode'),(762,1,'GDSNMeasurementUnitCode','E32','Litre Per Hour','Litre Per Hour',NULL,'7',1,'gdsnmeasurementunitcode'),(763,1,'GDSNMeasurementUnitCode','E34','Gigabyte','A unit of information equal to 109 bytes.',NULL,'7',1,'gdsnmeasurementunitcode'),(764,1,'GDSNMeasurementUnitCode','E35','Terabyte','A unit of information equal to 1012 bytes.',NULL,'7',1,'gdsnmeasurementunitcode'),(765,1,'GDSNMeasurementUnitCode','E37','Pixel','A unit of count defining the number of pixels (pixel: picture element).',NULL,'7',1,'gdsnmeasurementunitcode'),(766,1,'GDSNMeasurementUnitCode','E39','Dots per inch','A unit of count defining the number of dots per linear inch as a measure of the resolution or sharpness of a graphic image.',NULL,'7',1,'gdsnmeasurementunitcode'),(767,1,'GDSNMeasurementUnitCode','E4','Gross kilogram','A unit of mass defining the total number of kilograms before deductions.',NULL,'7',1,'gdsnmeasurementunitcode'),(768,1,'GDSNMeasurementUnitCode','E55','Use','A unit of count defining the number of times an object is used.',NULL,'7',1,'gdsnmeasurementunitcode'),(769,1,'GDSNMeasurementUnitCode','EA','Each','A unit of count defining the number of items regarded as separate units.',NULL,'7',1,'gdsnmeasurementunitcode'),(770,1,'GDSNMeasurementUnitCode','ELU','ELISA Units','Enzyme-linked immunosorbent assay unit, is always associated with a product and a method.',NULL,'7',1,'gdsnmeasurementunitcode'),(771,1,'GDSNMeasurementUnitCode','F27','Gram Per Hour','Gram Per Hour',NULL,'7',1,'gdsnmeasurementunitcode'),(772,1,'GDSNMeasurementUnitCode','FAH','Degree Fahrenheit','The Fahrenheit temperature scale, the freezing point of water is 32 degrees Fahrenheit (°F) and the boiling point 212 °F (at standard atmospheric pressure), placing the boiling and freezing points of water exactly 180 degrees apart.',NULL,'7',1,'gdsnmeasurementunitcode'),(773,1,'GDSNMeasurementUnitCode','FH','Micromole','One millionth (10 -6 ) of a mole.',NULL,'7',1,'gdsnmeasurementunitcode'),(774,1,'GDSNMeasurementUnitCode','FJ','Sizing Factor','Sizing Factor',NULL,'7',1,'gdsnmeasurementunitcode'),(775,1,'GDSNMeasurementUnitCode','FOT','Foot','The international foot is defined to be equal to 0.3048 meters.',NULL,'7',1,'gdsnmeasurementunitcode'),(776,1,'GDSNMeasurementUnitCode','FP','Pound per square foot','A non SI unit of Pressure approximately equal to 47.88025 PASCAL\'s.',NULL,'7',1,'gdsnmeasurementunitcode'),(777,1,'GDSNMeasurementUnitCode','FR','Foot Per Minute','The number of foot per minute the trade item or part of the trade item moves.',NULL,'7',1,'gdsnmeasurementunitcode'),(778,1,'GDSNMeasurementUnitCode','FS','Foot Per Second','The number of foot per second the trade item or part of the trade item moves.',NULL,'7',1,'gdsnmeasurementunitcode'),(779,1,'GDSNMeasurementUnitCode','FTK','Square foot','A square foot is an area of a square whose sides are exactly 1 foot in length.',NULL,'7',1,'gdsnmeasurementunitcode'),(780,1,'GDSNMeasurementUnitCode','FTQ','Cubic foot','A cubic foot is the volume of a cube of side length one foot (0.3048 m) .',NULL,'7',1,'gdsnmeasurementunitcode'),(781,1,'GDSNMeasurementUnitCode','G2','US Gallon Per Minute','US gallon per minute',NULL,'7',1,'gdsnmeasurementunitcode'),(782,1,'GDSNMeasurementUnitCode','G21','Cup (US)','Cup (US)',NULL,'7',1,'gdsnmeasurementunitcode'),(783,1,'GDSNMeasurementUnitCode','G23','Peck','A peck is an imperial and U.S. customary unit of dry volume, equivalent in each of these systems to 2 gallons, 8 dry quarts, or 16 dry pints.',NULL,'7',1,'gdsnmeasurementunitcode'),(784,1,'GDSNMeasurementUnitCode','G24','Tablespoon','Tablespoon. 1/2 fluid ounces, 3 teaspoons, 15 millilitres',NULL,'7',1,'gdsnmeasurementunitcode'),(785,1,'GDSNMeasurementUnitCode','G25','Teaspoon','Teaspoon. 1/6 fluid ounces or 5 millilitres',NULL,'7',1,'gdsnmeasurementunitcode'),(786,1,'GDSNMeasurementUnitCode','G26','Stere','The stere or stère is a unit of volume in the original metric system equal to one cubic metre. The stère is typically used for measuring large quantities of firewood or other cut wood,',NULL,'7',1,'gdsnmeasurementunitcode'),(787,1,'GDSNMeasurementUnitCode','GBQ','Gigabecquerel','A unit of activity equal to 109 becquerels.',NULL,'7',1,'gdsnmeasurementunitcode'),(788,1,'GDSNMeasurementUnitCode','GFI','Gram of Fissile Isotope','A unit of mass defining the number of grams of a fissile isotope (fissile isotope: an isotope whose nucleus is able to be split when irradiated with low energy neutrons).',NULL,'7',1,'gdsnmeasurementunitcode'),(789,1,'GDSNMeasurementUnitCode','GL','Gram Per Litre','Gram Per Litre:A unit of measurement of mass concentration that shows how many grams of a certain substance are present in one litre.',NULL,'7',1,'gdsnmeasurementunitcode'),(790,1,'GDSNMeasurementUnitCode','GLI','Gallon (UK)','The imperial (UK) gallon was legally defined as 4.54609 litres.',NULL,'7',1,'gdsnmeasurementunitcode'),(791,1,'GDSNMeasurementUnitCode','GLL','Gallon (US)','The U.S. liquid gallon is legally defined as 231 cubic inches, and is equal to exactly 3.785411784 litres or about 0.133680555 cubic feet.',NULL,'7',1,'gdsnmeasurementunitcode'),(792,1,'GDSNMeasurementUnitCode','GM','Gram per square metre','In the metric system, the density of all types of paper, paperboard, and fabric, is expressed in terms of grams per square meter (g/m2).This quantity is commonly called grammage both in English and French (ISO 536), though many English- speaking countries still refer to the \"weight\". The term density here is used somewhat incorrectly, as density is mass by volume. More precisely, it is a measure of the area density, areal density, or surface density.',NULL,'7',1,'gdsnmeasurementunitcode'),(793,1,'GDSNMeasurementUnitCode','GRM','Gram','A gram is defined as one one-thousandth of the kilogram (1×10-3 kg).',NULL,'7',1,'gdsnmeasurementunitcode'),(794,1,'GDSNMeasurementUnitCode','GRN','Grain','A grain or troy grain is precisely 64.79891 milligrams. Exactly 7,000 grains per avoirdupois pound.',NULL,'7',1,'gdsnmeasurementunitcode'),(795,1,'GDSNMeasurementUnitCode','GRO','Gross','A unit of count defining the number of units in multiples of 144 (12 x 12).',NULL,'7',1,'gdsnmeasurementunitcode'),(796,1,'GDSNMeasurementUnitCode','GWH','Gigawatt hour','A gigaawatt hour is 109 kilowat hour or 3.6 terajoules.',NULL,'7',1,'gdsnmeasurementunitcode'),(797,1,'GDSNMeasurementUnitCode','H49','Centimetre Per Hour','The number of centimetre per hour the trade item or part of the trade item moves.',NULL,'7',1,'gdsnmeasurementunitcode'),(798,1,'GDSNMeasurementUnitCode','H67','Millimetre Per Hour','The number of millimetre per hour the trade item or part of the trade item moves.',NULL,'7',1,'gdsnmeasurementunitcode'),(799,1,'GDSNMeasurementUnitCode','H79','French gauge','The French scale (most correctly abbreviated as Fr, but also often abbreviated as FR or F) is commonly used to measure the catheter size (Circumference is in millimeters), in which 1 Fr = 0.33 mm in diameter. In the French Gauge system as it is also known, the diameter in millimeters of the catheter can be determined by dividing the French size by 3, thus an increasing French size corresponds with a larger diameter catheter. The following equations summarize the relationships: D(mm) = Fr/3 or Fr = D(mm)*3',NULL,'7',1,'gdsnmeasurementunitcode'),(800,1,'GDSNMeasurementUnitCode','H81','Millimetre Per Minute','The number of millimetre per minute the trade item or part of the trade item moves.',NULL,'7',1,'gdsnmeasurementunitcode'),(801,1,'GDSNMeasurementUnitCode','H87','Piece','A unit of count defining the number of pieces (piece: a single item, article or exemplar).',NULL,'7',1,'gdsnmeasurementunitcode'),(802,1,'GDSNMeasurementUnitCode','HC','Hundred count','A unit of count defining the number of units counted in multiples of 100.',NULL,'7',1,'gdsnmeasurementunitcode'),(803,1,'GDSNMeasurementUnitCode','HD','Half dozen','A unit of count defining the number of units in multiplt of six (6).',NULL,'7',1,'gdsnmeasurementunitcode'),(804,1,'GDSNMeasurementUnitCode','HEP','Histamine Equivalent Prick','Histamine equivalent prick testing for allergen.',NULL,'7',1,'gdsnmeasurementunitcode'),(805,1,'GDSNMeasurementUnitCode','HGM','Hectogram','A hectogram is one hundred (100) grams',NULL,'7',1,'gdsnmeasurementunitcode'),(806,1,'GDSNMeasurementUnitCode','HLT','Hectolitre','A hectolitre is one hundred (100) litres.',NULL,'7',1,'gdsnmeasurementunitcode'),(807,1,'GDSNMeasurementUnitCode','HM','Mile Per Hour (statute mile)','The number of mile per hour the trade item or part of the trade item moves.',NULL,'7',1,'gdsnmeasurementunitcode'),(808,1,'GDSNMeasurementUnitCode','HTZ','Hertz','A unit of frequency defined as the number of complete cycles per second; it is the basic unit of frequency in the International System of Units (SI).',NULL,'7',1,'gdsnmeasurementunitcode'),(809,1,'GDSNMeasurementUnitCode','HUR','Hour','An hour is a unit of measurement of time of the duration of 60 minutes, or 3600 seconds. It is 1/24 of a median Earth day.',NULL,'7',1,'gdsnmeasurementunitcode'),(810,1,'GDSNMeasurementUnitCode','INH','Inches','An international inch is defined to be equal to 25.4 millimeters.',NULL,'7',1,'gdsnmeasurementunitcode'),(811,1,'GDSNMeasurementUnitCode','INK','Square inch','A square inch is an area of a square whose sides are exactly 1 inch in length.',NULL,'7',1,'gdsnmeasurementunitcode'),(812,1,'GDSNMeasurementUnitCode','INQ','Cubic inch','A cubic inch is the volume of a cube of side length one inch (0.254 m).',NULL,'7',1,'gdsnmeasurementunitcode'),(813,1,'GDSNMeasurementUnitCode','IU','Inch Per Second','The number of inch per second the trade item or part of the trade item moves.',NULL,'7',1,'gdsnmeasurementunitcode'),(814,1,'GDSNMeasurementUnitCode','JOU','Joule','A joule is the energy exerted by a force of one newton acting to move an object through a distance of one metre.',NULL,'7',1,'gdsnmeasurementunitcode'),(815,1,'GDSNMeasurementUnitCode','K14','Foot Per Hour','The number of foot per hour the trade item or part of the trade item moves.',NULL,'7',1,'gdsnmeasurementunitcode'),(816,1,'GDSNMeasurementUnitCode','K30','Gallon (US liquid) Per Second','Gallon (US liquid) per second',NULL,'7',1,'gdsnmeasurementunitcode'),(817,1,'GDSNMeasurementUnitCode','K43','Horsepower','Horsepower (electric) -  Automotive horsepower is defined as \"a unit of power equal to 550 foot-pounds per second (745.7 watts)\".\n',NULL,'7',1,'gdsnmeasurementunitcode'),(818,1,'GDSNMeasurementUnitCode','K6','Kilolitre','A kilolitre is one thousand (1000) litres.',NULL,'7',1,'gdsnmeasurementunitcode'),(819,1,'GDSNMeasurementUnitCode','KDW','Kilogram drained net weight','Kilogram drained net weight',NULL,'7',1,'gdsnmeasurementunitcode'),(820,1,'GDSNMeasurementUnitCode','KEL','Kelvin','Kelvin: a unit of absolute temperature equal to 1/273.16 of the absolute temperature of the triple point of water. One kelvin degree is equal to one Celsius degree.',NULL,'7',1,'gdsnmeasurementunitcode'),(821,1,'GDSNMeasurementUnitCode','KGM','Kilogram','A unit of mass equal to one thousand grams.',NULL,'7',1,'gdsnmeasurementunitcode'),(822,1,'GDSNMeasurementUnitCode','KHY','Kilogram of hydrogen peroxide','Kilogram of hydrogen peroxide',NULL,'7',1,'gdsnmeasurementunitcode'),(823,1,'GDSNMeasurementUnitCode','KHZ','Kilohertz','A unit of frenquecy equal to 1000 Hertz',NULL,'7',1,'gdsnmeasurementunitcode'),(824,1,'GDSNMeasurementUnitCode','KIU','Kallikrein inactivator unit.','Kallikrein Inactivator Unit per Milliliter definition: An arbitrary unit of a kallikrein inactivator concentration equal to the concentration at which one milliliter of the mixture contains one unit of the kallikrein inactivator',NULL,'7',1,'gdsnmeasurementunitcode'),(825,1,'GDSNMeasurementUnitCode','KJO','Kilojoule','A kilojoule is 1000 joules',NULL,'7',1,'gdsnmeasurementunitcode'),(826,1,'GDSNMeasurementUnitCode','KMA','Kilogram of methylamine','Kilogram of methylamine',NULL,'7',1,'gdsnmeasurementunitcode'),(827,1,'GDSNMeasurementUnitCode','KMH','Kilometre Per Hour','The number of kilometre per hour the trade item or part of the trade item moves.',NULL,'7',1,'gdsnmeasurementunitcode'),(828,1,'GDSNMeasurementUnitCode','KMT','Kilometre','A kilometre is one thousand (1000) metres',NULL,'7',1,'gdsnmeasurementunitcode'),(829,1,'GDSNMeasurementUnitCode','KNI','Kilogram of nitrogen','Kilogram of nitrogen',NULL,'7',1,'gdsnmeasurementunitcode'),(830,1,'GDSNMeasurementUnitCode','KNM','Kilonewton Per Square Metre','Kilonewton Per Square Metre',NULL,'7',1,'gdsnmeasurementunitcode'),(831,1,'GDSNMeasurementUnitCode','KNT','Knot','The number of knots the trade item or part of the trade item moves. A Knot is a unit of speed equal to one nautical mile (1.852 km) per hour, approximately 1.151 mph.',NULL,'7',1,'gdsnmeasurementunitcode'),(832,1,'GDSNMeasurementUnitCode','KO','The milliequivalence caustic potash per gram of product','The milliequivalence caustic potash per gram of product. A unit of count defining the number of milligrams of potassium hydroxide per gram of product as a measure of the concentration of potassium hydroxide in the product.',NULL,'7',1,'gdsnmeasurementunitcode'),(833,1,'GDSNMeasurementUnitCode','KPA','Kilopascal','Kilopascal- a thousand pascals (10 to the 3rd power)',NULL,'7',1,'gdsnmeasurementunitcode'),(834,1,'GDSNMeasurementUnitCode','KPH','Kilogram of potassium hydroxide (caustic potash)','Kilogram of potassium hydroxide (caustic potash)',NULL,'7',1,'gdsnmeasurementunitcode'),(835,1,'GDSNMeasurementUnitCode','KPO','Kilogram of potassium oxide','Kilogram of potassium oxide',NULL,'7',1,'gdsnmeasurementunitcode'),(836,1,'GDSNMeasurementUnitCode','KPP','Kilogram of phosphorus pentoxide (phosphoric anhydride)','Kilogram of phosphorus pentoxide (phosphoric anhydride)',NULL,'7',1,'gdsnmeasurementunitcode'),(837,1,'GDSNMeasurementUnitCode','KSD','Kilogram of substance 90% dry','Kilogram of substance 90% dry',NULL,'7',1,'gdsnmeasurementunitcode'),(838,1,'GDSNMeasurementUnitCode','KSH','Kilogram of sodium hydroxide (caustic soda)','Kilogram of sodium hydroxide (caustic soda)',NULL,'7',1,'gdsnmeasurementunitcode'),(839,1,'GDSNMeasurementUnitCode','KT','Kit','A unit of count defining the number of kits (kit: tub, barrel or pail).',NULL,'7',1,'gdsnmeasurementunitco